### Multi-Step Phone Input Validation

Source: https://github.com/catamphetamine/libphonenumber-js/blob/master/_autodocs/advanced-usage.md

Implement a multi-step validation process for user-entered phone numbers, starting with character extraction, then length validation, and finally full parsing and validation. This pattern helps provide immediate feedback to the user as they type.

```typescript
import { 
  parseIncompletePhoneNumber,
  validatePhoneNumberLength,
  parsePhoneNumber 
} from 'libphonenumber-js'

class PhoneInputValidator {
  private country: string

  constructor(country: string) {
    this.country = country
  }

  // Step 1: Extract phone characters as user types
  extractCharacters(input: string): string {
    return parseIncompletePhoneNumber(input)
  }

  // Step 2: Quick validation (length)
  validateLength(input: string): string | null {
    const result = validatePhoneNumberLength(input, this.country)
    if (!result) return null

    const messages: Record<string, string> = {
      'TOO_SHORT': 'Number too short',
      'TOO_LONG': 'Number too long',
      'INVALID_LENGTH': 'Invalid length for this country',
      'NOT_A_NUMBER': 'No valid digits',
      'INVALID_COUNTRY': 'Country not supported'
    }
    return messages[result] || 'Invalid'
  }

  // Step 3: Full parse and validate
  parse(input: string) {
    const phone = parsePhoneNumber(input, this.country)
    if (!phone?.isValid()) return null
    return phone
  }
}

// Usage in form
const validator = new PhoneInputValidator('US')

function onPhoneInput(e: Event) {
  const input = (e.target as HTMLInputElement).value

  // Extract valid characters
  const cleaned = validator.extractCharacters(input)

  // Check length
  const lengthError = validator.validateLength(cleaned)
  if (lengthError) {
    showError(lengthError)
    return
  }

  // Try to parse
  const phone = validator.parse(cleaned)
  if (phone) {
    showSuccess(phone.formatNational())
  }
}
```

